#define N 1024
int M[N][N];

// 1. Spatial Locality: Efficient Access (Row-major)
void row_major() {
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            M[i][j] *= 2; // Sequential memory access (Cache hits)
        }
    }
}

// 2. Spatial Locality: Inefficient Access
void col_major() {
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            M[i][j] *= 2; // Large memory stride (Cache misses)
        }
    }
}
//------------------------------------------------

// 3. Cache Line Alignment (False Sharing Avoidance, C++17)
// Assuming 64-byte cache line size
struct alignas(64) PaddedCounter {
    volatile long count; 
    // No explicit padding needed due to alignas() directive
};

// Good: Ensures separate cache lines for multithreaded access
PaddedCounter counters[2];

// Bad: c1 and c2 might share a cache line (False Sharing)
struct UnalignedCounter {
    volatile long c1;
    volatile long c2; 
};
